// AI SDK 5 + OpenAI strict — tools + structured output
import { generateText } from 'ai';
import { openai } from '@ai-sdk/openai';
import { z } from 'zod';

const { toolCalls } = await generateText({
  model: openai('gpt-4o-mini'),
  tools: {
    search: { description: 'Search docs', parameters: z.object({ q: z.string() }) },
    book: { description: 'Book meeting', parameters: z.object({ date: z.string() }) }
  },
  prompt: 'Find refund policy and book follow-up'
});
// loop: execute tools, append tool results, continue

// Strict answer (no tools, guaranteed JSON)
import { generateObject } from 'ai';
const { object } = await generateObject({
  model: openai('gpt-4o-mini'),
  schema: z.object({ refundDays: z.number(), policyUrl: z.string().url() }),
  prompt: 'Extract refund policy from context: ...'
});
