```typescript
// app/api/chat/route.ts — AI SDK 5 server
import { streamText, convertToModelMessages } from 'ai';
import { openai } from '@ai-sdk/openai';

export async function POST(req: Request) {
  const { messages } = await req.json();
  const result = streamText({
    model: openai('gpt-4o-mini'),
    system: 'You are a helpful assistant. Cite sources.',
    messages: convertToModelMessages(messages),
  });
  return result.toUIMessageStreamResponse(); // data-stream for useChat
}

// app/chat.tsx — client
'use client';
import { useChat } from '@ai-sdk/react';
import { DefaultChatTransport } from 'ai';

export function Chat() {
  const { messages, sendMessage, status, stop } = useChat({
    transport: new DefaultChatTransport({ api: '/api/chat' })
  });
  return (
    <>
      {messages.map(m => <div key={m.id}>{m.parts.map((p,i) => p.type==='text' ? <span key={i}>{p.text}</span> : null)}</div>)}
      <button onClick={() => sendMessage({ text: 'Hello' })} disabled={status==='streaming'}>Send</button>
      {status==='streaming' && <button onClick={stop}>Stop</button>}
    </>
  );
}
```

