// Raw streaming without AI SDK (shows abort + SSE)
export async function POST(req: Request) {
  const controller = new AbortController();
  req.signal.addEventListener('abort', () => controller.abort()); // client nav aborts billing
  const stream = await openai.chat.completions.create({
    model: 'gpt-4o-mini', stream: true, messages: [{ role: 'user', content: 'hi' }]
  }, { signal: controller.signal });

  const readable = new ReadableStream({
    async start(c) {
      for await (const chunk of stream) {
        const delta = chunk.choices[0]?.delta?.content;
        if (delta) c.enqueue(new TextEncoder().encode(`data: ${JSON.stringify({ delta })}\n\n`));
      }
      c.close();
    }
  });
  return new Response(readable, { headers: { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache' } });
}
```

