```typescript
// Agent loop with budget + tiered approval
import { generateText } from 'ai';
import { openai } from '@ai-sdk/openai';

const caps = { maxSteps: 12, maxCost: 0.5, maxMs: 60000 };
const start = Date.now();
let cost = 0;
for (let step = 0; step < caps.maxSteps; step++) {
  if (cost > caps.maxCost || Date.now() - start > caps.maxMs) throw new Error('budget_exceeded');
  const { text, toolCalls, usage } = await generateText({ model: openai('gpt-4o'), prompt: task, tools });
  cost += usage.inputTokens * 0.00015 + usage.outputTokens * 0.0006;
  for (const tc of toolCalls) {
    if (tierOf(tc.toolName) >= 2 && !await confirm(tc)) { await logDecision('denied', tc); continue; }
    const out = await execTool(tc);
    task += `\nTool ${tc.toolName}: ${JSON.stringify(out)}`;
  }
  if (!toolCalls.length) break;
}
